{
  "items": [
    {
      "title": "GERDA: The German Election Database",
      "url_or_doi": "https://doi.org/10.1038/s41597-025-04811-5",
      "justification": "A comprehensive research dataset covering German federal, state, and municipal elections during the 1990s. Includes election results at municipality, county, and constituency levels, with party vote shares and harmonized geographic boundaries. Particularly useful for analyzing regional voting patterns, electoral changes following German reunification, and differences between East and West Germany."
    },
    {
      "title": "GERDA: German Election Database — Election Data Downloads",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Provides downloadable election datasets in CSV, Excel, and RDS formats. Includes federal election results for 1990, 1994, and 1998, as well as state and municipal election results throughout the 1990s. Offers harmonized datasets that account for changes in administrative boundaries, making it especially suitable for longitudinal electoral analysis."
    },
    {
      "title": "German Federal Election 1990 — Official Election Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/1990.html",
      "justification": "Official historical election data published by Germany's Federal Returning Officer. Covers the December 2, 1990 Bundestag election, the first federal election following German reunification. Contains party vote totals, first and second votes, voter turnout, parliamentary seats, and constituency-level results. Particularly valuable for studying the political consequences of reunification."
    },
    {
      "title": "German Federal Election 1994 — Official Election Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/1994.html",
      "justification": "Official results from the October 16, 1994 Bundestag election. Includes constituency-level election results, party vote shares, voter participation, and parliamentary seat allocations. Useful for examining electoral competition during Helmut Kohl's administration and comparing voting behavior between the 1990 and 1994 federal elections."
    },
    {
      "title": "German Federal Election 1998 — Official Election Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/1998.html",
      "justification": "Official election results for the September 27, 1998 Bundestag election, which resulted in a change of government from Helmut Kohl's CDU/CSU-led coalition to Gerhard Schröder's SPD-Green coalition. Contains party vote totals, turnout, first and second votes, constituency-level results, and seat distributions. Suitable for analyzing electoral realignment during the late 1990s."
    },
    {
      "title": "GESIS — German Federal Election Studies",
      "url_or_doi": "https://www.gesis.org/en/elections/german-federal-elections",
      "justification": "A major collection of representative election surveys covering German federal elections since 1949, including the elections of 1990, 1994, and 1998. Contains individual-level survey data on electoral preferences, political attitudes, party identification, and voting behavior. Particularly useful for studying why German voters supported particular political parties during the 1990s."
    },
    {
      "title": "GESIS — German State Election Studies (Landtagswahlen)",
      "url_or_doi": "https://www.gesis.org/en/elections/german-state-elections",
      "justification": "Collection of representative surveys associated with German state parliamentary elections, including numerous elections conducted between 1990 and 1999. Provides information on political attitudes, voting intentions, electoral preferences, and state-level electoral behavior. Useful for studying regional political differences and the development of party competition in reunified Germany."
    },
    {
      "title": "GESIS Research Data Center Elections",
      "url_or_doi": "https://www.konsortswd.de/en/services/research/all-datacentres/fdz-wahlen/",
      "justification": "Research data infrastructure providing access to historical German election studies. Its holdings include federal election surveys from 1949 to 2005, state election studies beginning in 1962, Politbarometer surveys beginning in 1977, and Forsa-Bus surveys beginning in 1991. Particularly valuable for finding individual-level electoral behavior datasets from the entire 1990s."
    },
    {
      "title": "GESIS — Kiel Election Studies (Kieler Wahlstudien), 1976–1990",
      "url_or_doi": "https://www.gesis.org/en/elections/german-federal-elections",
      "justification": "Historical election survey series covering German federal elections between 1976 and 1990. Includes studies associated with the 1990 election, providing evidence about political preferences and voter behavior around the time of German reunification. Useful for comparing electoral attitudes before and after reunification. The datasets and documentation are available in German."
    },
    {
      "title": "GERDA — German State Election Results, 1946–2026",
      "url_or_doi": "https://www.german-elections.com/election-data/",
      "justification": "Municipality-level results from German state parliamentary elections, including those conducted throughout the 1990s. Provides historical party vote shares and geographically harmonized versions covering elections from 1990 onward. Suitable for investigating regional electoral trends, party support, and differences between eastern and western German states."
    },
    {
      "title": "GERDA — German Municipal Election Results",
      "url_or_doi": "https://github.com/awiedem/german_election_data",
      "justification": "Open research repository containing German municipal election datasets covering elections during the 1990s. Includes local party vote shares and geographic identifiers, with harmonized versions for comparisons across time. Especially useful for studying grassroots political competition, the development of local party systems, and electoral differences between municipalities following reunification."
    },
    {
      "title": "GESIS — Politbarometer Election and Political Opinion Surveys",
      "url_or_doi": "https://www.gesis.org/en/elections",
      "justification": "Collection of German political opinion and election-related surveys, including Politbarometer data spanning the entire 1990s. Provides information on voting intentions, political preferences, government evaluations, and attitudes toward political parties. Particularly suitable for examining changes in public opinion between the federal elections of 1990, 1994, and 1998."
    },
    {
      "title": "German Federal Election 1998 — Additional Constituency and Postal Voting Results",
      "url_or_doi": "https://www.bundeswahlleiterin.de/bundestagswahlen/1998/weitere-ergebnisse.html",
      "justification": "Supplementary official election data for the 1998 German federal election. Includes constituency-level results distinguishing polling-station voters from postal voters. Useful for studying differences in voting methods and party preferences, as well as geographic variation in electoral participation."
    }
  ]
}
